css:
.scbrandsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2e22;
    background: linear-gradient(160deg, #f1f6ec 0%, #e6f0df 100%);
    border-radius: 18px;
}

.scbrandsim-container * {
    box-sizing: border-box;
}

.scbrandsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1f5130 0%, #2e7d44 55%, #6aa84f 100%);
    color: #f3faef;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(31, 81, 48, 0.30);
}

.scbrandsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.scbrandsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #d4ecc4;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.scbrandsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7f4de;
}

.scbrandsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c5b39;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.scbrandsim-period-counter #currentDay,
.scbrandsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f5130;
}

.scbrandsim-round-name {
    background: #d3e8c5;
    color: #1f5130;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.scbrandsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4a16;
    background: #f6e4d2;
    padding: 4px 12px;
    border-radius: 999px;
}

.scbrandsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.scbrandsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6e6cb;
    box-shadow: 0 4px 14px rgba(31, 81, 48, 0.06);
    border-top: 4px solid #6aa84f;
}

.scbrandsim-card-supply { border-top-color: #2e7d44; }
.scbrandsim-card-credibility { border-top-color: #4f8f55; }
.scbrandsim-card-buyer { border-top-color: #2b6f8c; }
.scbrandsim-card-roi { border-top-color: #c08a1e; }

.scbrandsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a8369;
}

.scbrandsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f5130;
}

.scbrandsim-card-supply .scbrandsim-value { color: #2e7d44; }
.scbrandsim-card-credibility .scbrandsim-value { color: #4f8f55; }
.scbrandsim-card-buyer .scbrandsim-value { color: #2b6f8c; }
.scbrandsim-card-roi .scbrandsim-value { color: #c08a1e; }

.scbrandsim-sublabel {
    font-size: 0.76rem;
    color: #7a917a;
    line-height: 1.35;
}

.scbrandsim-credibility-greenwash .scbrandsim-value { color: #c0392b; }
.scbrandsim-credibility-strong .scbrandsim-value { color: #2e7d44; }

.scbrandsim-roi-loss .scbrandsim-value { color: #c0392b; }

.scbrandsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f5130;
    color: #eef7e8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.scbrandsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.scbrandsim-budget-over #budgetDisplay {
    color: #ffb3a3;
}

.scbrandsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #6aa84f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 81, 48, 0.05);
}

.scbrandsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.scbrandsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f5130;
    margin-bottom: 6px;
}

.scbrandsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #33493a;
}

.scbrandsim-briefing-text strong { color: #2e7d44; }
.scbrandsim-briefing-text em { color: #9a4a16; font-style: italic; }

.scbrandsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6e6cb;
    box-shadow: 0 4px 14px rgba(31, 81, 48, 0.06);
}

.scbrandsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f5130;
    border-bottom: 2px solid #e6f0df;
    padding-bottom: 8px;
}

.scbrandsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c4a33;
    margin: 14px 0 6px;
}

.scbrandsim-container select,
.scbrandsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcd6ac;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fbf3;
    color: #1f2e22;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.scbrandsim-container select:focus,
.scbrandsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2e7d44;
    box-shadow: 0 0 0 3px rgba(46, 125, 68, 0.15);
}

.scbrandsim-container select option {
    background-color: #ffffff;
    color: #1f2e22;
}

.scbrandsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2e7d44;
}

.scbrandsim-range-readout,
.scbrandsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c5b39;
    margin-top: 4px;
}

.scbrandsim-range-readout span:last-child,
.scbrandsim-alloc-readout span:nth-child(2) {
    color: #2e7d44;
    font-weight: 800;
}

.scbrandsim-hint {
    font-size: 0.8rem;
    color: #7a917a;
    margin-top: 4px;
    line-height: 1.4;
}

.scbrandsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.scbrandsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f2f8ec;
    border: 1px solid #dcebd0;
    border-radius: 9px;
    padding: 8px 12px;
}

.scbrandsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c4a33;
}

.scbrandsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.scbrandsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.scbrandsim-container .btn-primary {
    background: linear-gradient(135deg, #2e7d44 0%, #6aa84f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(46, 125, 68, 0.28);
}

.scbrandsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.scbrandsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcd6ac;
    color: #6a8369;
}

.scbrandsim-coach {
    background: #1f5130;
    color: #eef7e8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 81, 48, 0.22);
}

.scbrandsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9ed184;
    margin-bottom: 8px;
}

.scbrandsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.scbrandsim-coach-body strong { color: #ffe08a; }
.scbrandsim-coach-body em { color: #ffc1ad; font-style: italic; }

.scbrandsim-history,
.scbrandsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6e6cb;
    box-shadow: 0 4px 14px rgba(31, 81, 48, 0.06);
}

.scbrandsim-history h3,
.scbrandsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f5130;
}

.scbrandsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c4a33;
}

.scbrandsim-container table#usfHistoryTable th {
    background: #ebf3e4;
    color: #1f5130;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e6c9;
}

.scbrandsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef4e9;
}

.scbrandsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fbf4;
}

.scbrandsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .scbrandsim-container {
        padding: 14px;
    }
    .scbrandsim-header h1 {
        font-size: 1.7rem;
    }
    .scbrandsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .scbrandsim-value {
        font-size: 2rem;
    }
    .scbrandsim-clock {
        margin-left: 0;
    }
    .scbrandsim-period-counter {
        font-size: 0.88rem;
    }
    .scbrandsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .scbrandsim-alloc-row {
        flex-wrap: wrap;
    }
    .scbrandsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .scbrandsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .sc-cm-*) ── */
.sc-cm { margin-top: 8px; }
.sc-cm-incomplete { text-align: center; color: #6a8369; font-size: 1rem; padding: 18px; }
.sc-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.sc-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #1f5130 0%, #2e7d44 60%, #6aa84f 100%); color: #f3faef; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(31, 81, 48, 0.28); }
.sc-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.sc-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.sc-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #d4ecc4; }
.sc-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #ffffff; border: 1px solid #d6e6cb; border-left: 5px solid #2e7d44; border-radius: 14px; padding: 16px 20px; }
.sc-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6a8369; }
.sc-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #1f5130; line-height: 1.15; }
.sc-cm-section { margin-bottom: 16px; }
.sc-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #2c5b39; margin-bottom: 8px; }
.sc-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.sc-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.sc-cm-ok { background: #e3f2d6; color: #1f5130; border-color: #bcdca6; }
.sc-cm-no { background: #f7e0da; color: #a03422; border-color: #e6b6aa; }
.sc-cm-ico { font-weight: 800; }
.sc-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.sc-cm-kpi { background: #ffffff; border: 1px solid #d6e6cb; border-top: 4px solid #6aa84f; border-radius: 12px; padding: 14px 12px; text-align: center; }
.sc-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #1f5130; line-height: 1; }
.sc-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #2c5b39; }
.sc-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #7a917a; }
.sc-cm-insights { margin: 0; padding-left: 18px; color: #1f2e22; }
.sc-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .sc-cm-head { flex-direction: column; } .sc-cm-score { min-width: 0; } }

