(function() {
    'use strict';

    class SupplyChainBrandAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Supply-Chain Brand`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Cláirseach Dairy Group).
            this.START_SUPPLY = 60;        // 60% farms already verification-ready (40% gap)
            this.START_CREDIBILITY = 12;   // brand asserted, not verified
            this.START_BUYER = 20;         // Nordmilk has issued an ultimatum
            this.BUDGET_CAP = 9.0;         // €9M once-off, in millions
            this.GAP_COST = 3.4;           // ~€3.4M closes the full 40% gap
            this.NORDMILK_REVENUE = 242;   // €242M at risk (22% of revenue)
            this.TARGET_SUPPLY = 95;       // verified-supply target to qualify the Nordmilk audit

            // Concept-correct levers (the strict best-scorers among siblings).
            this.TRUE_CLAIM = `verified`;
            this.TRUE_PRIORITY = `nordmilk`;
            this.TRUE_TARGET = `nordmilkfirst`;
            this.TRUE_ARCH = `both`;
            this.TRUE_POSITION = `farmlevel`;
            this.TRUE_SCENARIO = `stress`;
        }

        _fmtMoney(m) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const v = Math.round(Number(m) * 10) / 10;
            const num = v.toFixed(1);
            if (lang === `es`) {
                return num.replace(`.`, `,`) + ` M€`;
            }
            return `€` + num + `M`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    supply: this.START_SUPPLY,
                    credibility: this.START_CREDIBILITY,
                    buyer: this.START_BUYER,
                    roi: 0,
                    budgetUsed: 0,
                    greenwashFlag: false,
                    nordmilkLost: false,
                    supplyHistory: [this.START_SUPPLY],
                    credibilityHistory: [this.START_CREDIBILITY],
                    buyerHistory: [this.START_BUYER],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed a MIDDLING/neutral mix — never the textbook-correct play.
                state.decisions = {
                    claim: `grassfed`,
                    priority: `spread`,
                    honesty: 50,
                    target: `all`,
                    coop: 40,
                    farmer: 40,
                    shared: 20,
                    verify: 2,
                    arch: `consumer`,
                    position: `generic`,
                    proof: 0.5,
                    restraint: 50,
                    trade: 1,
                    pull: 1,
                    scenario: `base`,
                    defence: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const budgetLeft = () => this.BUDGET_CAP - (state.domainState.budgetUsed || 0);

            if (round === 1) {
                const cl = document.getElementById(`claimInput`);
                const pr = document.getElementById(`priorityInput`);
                const hon = document.getElementById(`honestyInput`);
                if (cl) decisions.claim = cl.value;
                if (pr) decisions.priority = pr.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const tg = document.getElementById(`targetInput`);
                if (tg) decisions.target = tg.value;
                const coop = document.getElementById(`coopInput`);
                const farmer = document.getElementById(`farmerInput`);
                const shared = document.getElementById(`sharedInput`);
                if (coop) decisions.coop = parseFloat(coop.value);
                if (farmer) decisions.farmer = parseFloat(farmer.value);
                if (shared) decisions.shared = parseFloat(shared.value);
                const parts = [decisions.coop, decisions.farmer, decisions.shared];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_split_negative`); return false;
                }
                const total = Math.round(decisions.coop + decisions.farmer + decisions.shared);
                if (total !== 100) {
                    warn(`warn_split_total`); return false;
                }
                const vf = document.getElementById(`verifyInput`);
                if (vf) decisions.verify = parseFloat(vf.value);
                if (!Number.isFinite(decisions.verify) || decisions.verify < 0) {
                    warn(`warn_verify_negative`); return false;
                }
                if (decisions.verify > budgetLeft() + 0.001) {
                    warn(`warn_over_budget`); return false;
                }
            } else if (round === 3) {
                const ar = document.getElementById(`archInput`);
                const po = document.getElementById(`positionInput`);
                if (ar) decisions.arch = ar.value;
                if (po) decisions.position = po.value;
                const pf = document.getElementById(`proofInput`);
                const re = document.getElementById(`restraintInput`);
                if (pf) decisions.proof = parseFloat(pf.value);
                if (re) decisions.restraint = parseInt(re.value, 10);
                if (!Number.isFinite(decisions.proof) || decisions.proof < 0) {
                    warn(`warn_proof_negative`); return false;
                }
                if (decisions.proof > budgetLeft() + 0.001) {
                    warn(`warn_over_budget`); return false;
                }
                if (!Number.isFinite(decisions.restraint) || decisions.restraint < 0 || decisions.restraint > 100) {
                    warn(`warn_restraint_range`); return false;
                }
            } else if (round === 4) {
                const tr = document.getElementById(`tradeInput`);
                const pu = document.getElementById(`pullInput`);
                const sc = document.getElementById(`scenarioInput`);
                const de = document.getElementById(`defenceInput`);
                if (tr) decisions.trade = parseFloat(tr.value);
                if (pu) decisions.pull = parseFloat(pu.value);
                if (sc) decisions.scenario = sc.value;
                if (de) decisions.defence = parseInt(de.value, 10);
                if (!Number.isFinite(decisions.trade) || decisions.trade < 0 || !Number.isFinite(decisions.pull) || decisions.pull < 0) {
                    warn(`warn_alloc_negative`); return false;
                }
                if ((decisions.trade + decisions.pull) > budgetLeft() + 0.001) {
                    warn(`warn_over_budget`); return false;
                }
                if (!Number.isFinite(decisions.defence) || decisions.defence < 0 || decisions.defence > 100) {
                    warn(`warn_defence_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas. supply = verified farms; credibility = durable verified-promise brand;
            // buyer = Nordmilk/B2B confidence; brandPush = how much brand promise was made this round
            // (used to detect greenwashing when it outruns verified supply).
            let supplyDelta = 0, credDelta = 0, buyerDelta = 0, brandPush = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: the one claim you can defend today + where the real value at risk sits.
                if (d.claim === this.TRUE_CLAIM) {
                    credDelta += 10; buyerDelta += 8; coachKey = `coach_r1_claim_right`;
                } else if (d.claim === `grassfed`) {
                    credDelta += 1; brandPush += 6;
                } else if (d.claim === `lowcarbon`) {
                    credDelta -= 6; brandPush += 14; coachKey = `coach_r1_overclaim`;
                } else { // netzero
                    credDelta -= 10; brandPush += 20; coachKey = `coach_r1_netzero`;
                }

                // Protect the €242M Nordmilk volume and the rich nutritional margin.
                if (d.priority === this.TRUE_PRIORITY) {
                    buyerDelta += 12; credDelta += 4;
                    if (d.claim === this.TRUE_CLAIM) coachKey = `coach_r1_diag_sharp`;
                } else if (d.priority === `commodity`) {
                    buyerDelta -= 6; coachKey = `coach_r1_commodity`;
                } else if (d.priority === `consumer`) {
                    buyerDelta -= 8; coachKey = `coach_r1_consumer`;
                } else { // spread
                    buyerDelta -= 4;
                }

                // Honesty: discipline to keep the claim inside the proven reality.
                if (d.honesty >= 60) { credDelta += 7; }
                else if (d.honesty <= 25) { credDelta -= 7; brandPush += 6; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.claim === this.TRUE_CLAIM && d.priority === this.TRUE_PRIORITY) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Commit the supply chain — verification target, sequencing, funding split, spend.
                switch (d.target) {
                    case `nordmilkfirst`: supplyDelta += 18; buyerDelta += 12; credDelta += 6; coachKey = `coach_r2_sequenced`; break;
                    case `all`: supplyDelta += 12; buyerDelta += 4; credDelta -= 2; coachKey = `coach_r2_unsequenced`; break;
                    case `minimum`: supplyDelta += 6; buyerDelta -= 4; coachKey = `coach_r2_minimum`; break;
                    case `defer`: supplyDelta -= 4; buyerDelta -= 12; brandPush += 10; coachKey = `coach_r2_defer`; break;
                }

                // Funding split: shared (advisory + co-payment) best protects both the AGM and the budget.
                // Co-op-heavy protects farmer price but burns scarce budget; farmer-heavy risks AGM revolt.
                const shared = d.shared, coop = d.coop, farmer = d.farmer;
                if (shared >= 50) {
                    supplyDelta += 8; buyerDelta += 3; if (coachKey === `coach_default`) coachKey = `coach_r2_shared`;
                } else if (farmer >= 60) {
                    supplyDelta -= 8; coachKey = `coach_r2_farmer`;
                } else if (coop >= 70) {
                    supplyDelta += 2; coachKey = `coach_r2_coop`;
                } else {
                    supplyDelta += 3;
                }

                // Verification spend: closing the ~€3.4M gap drives verified supply hard; under-funding stalls it.
                spend += d.verify;
                if (d.verify >= 3.0) { supplyDelta += 14; credDelta += 4; }
                else if (d.verify >= 1.5) { supplyDelta += 8; credDelta += 2; }
                else { supplyDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r2_underfund`; }

                summaryKey = (d.target === this.TRUE_TARGET && d.verify >= 1.5) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Build the national brand programme — architecture, positioning, proof, restraint.
                switch (d.arch) {
                    case `both`: credDelta += 10; buyerDelta += 12; brandPush += 8; coachKey = `coach_r3_both`; break;
                    case `b2b`: credDelta += 6; buyerDelta += 10; brandPush += 4; coachKey = `coach_r3_b2b`; break;
                    case `consumer`: credDelta += 2; buyerDelta -= 8; brandPush += 14; coachKey = `coach_r3_consumer`; break;
                    case `corporate`: credDelta -= 4; buyerDelta -= 4; brandPush += 6; coachKey = `coach_r3_corporate`; break;
                }

                // Positioning: evidence-based farm-level differentiation beats generic adjectives.
                switch (d.position) {
                    case `farmlevel`: credDelta += 12; buyerDelta += 8; if (d.arch === this.TRUE_ARCH) coachKey = `coach_r3_differentiated`; break;
                    case `generic`: credDelta -= 8; buyerDelta -= 4; coachKey = `coach_r3_generic`; break;
                    case `price`: credDelta -= 6; buyerDelta -= 2; coachKey = `coach_r3_price`; break;
                    case `heritage`: credDelta -= 2; brandPush += 6; coachKey = `coach_r3_heritage`; break;
                }

                // Proof / measurement system — the load-bearing investment that turns audits into claims.
                spend += d.proof;
                if (d.proof >= 1.0) { credDelta += 12; buyerDelta += 6; }
                else if (d.proof >= 0.5) { credDelta += 5; buyerDelta += 2; }
                else { credDelta -= 8; brandPush += 6; coachKey = `coach_r3_noproof`; }

                // Claim restraint: keep brand promise inside Round 2's verified reality.
                if (d.restraint >= 60) { credDelta += 6; }
                else if (d.restraint <= 25) { credDelta -= 6; brandPush += 10; coachKey = `coach_r3_overpromise`; }

                summaryKey = (d.arch !== `consumer` && d.arch !== `corporate` && d.position === this.TRUE_POSITION && d.proof >= 0.5) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Allocate & defend: trade vs pull spend, scenario discipline, board/buyer defence.
                spend += d.trade + d.pull;

                // B2B trade marketing reaches the buyer holding the €242M; reasonable investment helps.
                if (d.trade >= 1.0) { buyerDelta += 8; credDelta += 2; }
                else if (d.trade >= 0.4) { buyerDelta += 4; }
                else { buyerDelta -= 4; coachKey = `coach_r4_notrade`; }

                // Consumer pull is fine in moderation but is brand promise — it must not outrun verified supply.
                brandPush += d.pull * 5;
                if (d.pull >= 2.5) { credDelta += 2; brandPush += 6; coachKey = `coach_r4_overpull`; }
                else if (d.pull >= 0.5) { credDelta += 4; buyerDelta += 2; }

                // Scenario discipline: a plan that survives the 3% premium / 2% lift floor is resilient.
                switch (d.scenario) {
                    case `stress`: credDelta += 8; buyerDelta += 10; coachKey = (coachKey === `coach_default`) ? `coach_r4_stress` : coachKey; break;
                    case `base`: buyerDelta += 2; break;
                    case `optimistic`: credDelta -= 4; buyerDelta -= 8; coachKey = `coach_r4_optimistic`; break;
                }

                // Defence: how firmly you hold that brand spend never outran verified supply.
                if (d.defence >= 60) { buyerDelta += 5; credDelta += 3; if (d.scenario === this.TRUE_SCENARIO && coachKey !== `coach_r4_optimistic`) coachKey = `coach_r4_defended`; }
                else if (d.defence <= 25) { buyerDelta -= 5; }

                summaryKey = (d.scenario === this.TRUE_SCENARIO && d.trade >= 0.4 && d.pull < 2.5) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;

            // Supply moves on its delta (verified-supply % of farms).
            ds.supply = Math.max(0, Math.min(100, ds.supply + supplyDelta));

            // Brand credibility moves on its delta — but it is GATED by verified supply. A brand
            // that promises more than the supply chain can verify is greenwashing: every unit of
            // brand push beyond the verified-supply ceiling is clawed back, and it hits the buyer.
            ds.credibility = Math.max(0, Math.min(100, ds.credibility + credDelta));
            const ceiling = ds.supply;                       // credibility cannot durably exceed verified supply
            let greenwashGap = 0;
            if (ds.credibility > ceiling) {
                greenwashGap = ds.credibility - ceiling;
                ds.credibility = ceiling + greenwashGap * 0.25;   // most of the over-claim is not durable
            }
            // Aggressive brand push while supply lags is a direct greenwashing penalty.
            const overreach = Math.max(0, brandPush - Math.max(0, ds.supply - this.START_SUPPLY) * 0.8);
            if (overreach > 12) {
                const hit = Math.min(14, (overreach - 12) * 0.6);
                ds.credibility = Math.max(0, ds.credibility - hit);
                buyerDelta -= hit * 0.5;
                if (greenwashGap > 6 || overreach > 22) ds.greenwashFlag = true;
            }

            ds.buyer = Math.max(0, Math.min(100, ds.buyer + buyerDelta));

            // Scenario-weighted ROI projection (€M annual). Premium and demand lift are uncertain
            // ranges (3–8% premium, 2–6% lift). The realised premium is gated by verified supply and
            // credibility; the demand lift by buyer confidence. The plan is modelled against the
            // chosen scenario, but Nordmilk only stays if buyer confidence holds.
            let prem, lift;
            if (d.scenario === `stress`) { prem = 0.03; lift = 0.02; }
            else if (d.scenario === `optimistic`) { prem = 0.08; lift = 0.06; }
            else { prem = 0.05; lift = 0.04; }
            // Effective premium scales with how much of the supply is genuinely verified & credible.
            const effFactor = (ds.supply / 100) * (ds.credibility / 100);
            const buyerFactor = ds.buyer / 100;
            // Nordmilk revenue retained scales with buyer confidence; below a floor it re-tenders.
            ds.nordmilkLost = (round === this.ROUNDS.length && ds.buyer < 40);
            const retained = this.NORDMILK_REVENUE * Math.min(1, buyerFactor + 0.15);
            const premiumValue = retained * prem * effFactor;
            const liftValue = retained * lift * buyerFactor * 0.6;
            const grossPayoff = premiumValue + liftValue;
            // Net of the once-off budget amortised over the plan horizon.
            ds.roi = Math.round((grossPayoff - ds.budgetUsed * 0.25) * 10) / 10;
            if (ds.greenwashFlag) ds.roi = Math.round((ds.roi - 4) * 10) / 10;

            ds.supplyHistory.push(Math.round(ds.supply));
            ds.credibilityHistory.push(Math.round(ds.credibility));
            ds.buyerHistory.push(Math.round(ds.buyer));

            // v1.1.0 fix — persist composite where Express grading/reporting reads it
            // (results_utils.php express_resolveDomainScore -> performance.overallScore, then top-level score).
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                supply: Math.round(ds.supply),
                supplyDelta: Math.round(supplyDelta),
                credibility: Math.round(ds.credibility),
                credDelta: Math.round(credDelta),
                buyer: Math.round(ds.buyer),
                buyerDelta: Math.round(buyerDelta),
                roi: ds.roi,
                budgetUsed: ds.budgetUsed,
                greenwashFlag: ds.greenwashFlag,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: composite,
                overallScore: composite
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`supplyDisplay`, `domainState.supply`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`credibilityDisplay`, `domainState.credibility`, (v) => {
                const card = document.querySelector(`.scbrandsim-card-credibility`);
                if (card) {
                    const ds = window.mySimulation.state.domainState;
                    card.classList.toggle(`scbrandsim-credibility-greenwash`, !!(ds && ds.greenwashFlag));
                    card.classList.toggle(`scbrandsim-credibility-strong`, Number(v) >= 70 && !(ds && ds.greenwashFlag));
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`buyerDisplay`, `domainState.buyer`, (v) => Math.round(Number(v)));
            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => {
                const card = document.querySelector(`.scbrandsim-card-roi`);
                if (card) card.classList.toggle(`scbrandsim-roi-loss`, Number(v) < 0);
                return this._fmtMoney(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.scbrandsim-budget-bar`);
                if (bar) bar.classList.toggle(`scbrandsim-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return this._fmtMoney(Number(v)) + ` / ` + this._fmtMoney(this.BUDGET_CAP);
            });

            const self = this;

            // Honesty slider readout.
            const hon = document.getElementById(`honestyInput`);
            const honReadout = document.getElementById(`honestyReadout`);
            if (hon && honReadout) {
                honReadout.textContent = hon.value;
                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            // Restraint slider readout.
            const re = document.getElementById(`restraintInput`);
            const reReadout = document.getElementById(`restraintReadout`);
            if (re && reReadout) {
                reReadout.textContent = re.value;
                re.addEventListener(`input`, function() { reReadout.textContent = re.value; });
            }

            // Funding-split live total.
            const splitIds = [`coopInput`, `farmerInput`, `sharedInput`];
            const splitReadout = document.getElementById(`splitReadout`);
            const recompute = function() {
                let total = 0;
                splitIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (splitReadout) splitReadout.textContent = total;
                const bar = document.querySelector(`.scbrandsim-alloc-readout`);
                if (bar) bar.style.color = (total !== 100) ? `#c0392b` : ``;
            };
            splitIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
