        getChartData(state) {
            const ds = state.domainState;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const labels = ds.supplyHistory.map((_, i) => (i === 0 ? t(`chart_start`) : `R` + i));
            return {
                brandChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.supplyHistory },
                        { data: ds.credibilityHistory },
                        { data: ds.buyerHistory }
                    ]
                }
            };
