        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const supply = Math.round(ds.supply);
            const credibility = Math.round(ds.credibility);
            const buyer = Math.round(ds.buyer);
            const roi = ds.roi;
            return Math.round(
                Math.min(100, supply) * 0.30 +
                credibility * 0.30 +
                buyer * 0.25 +
                Math.max(0, Math.min(100, (roi / 12) * 100)) * 0.15
            );
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const supply = Math.round(ds.supply);
            const credibility = Math.round(ds.credibility);
            const buyer = Math.round(ds.buyer);
            const roi = ds.roi;

            const verified = supply >= this.TARGET_SUPPLY;
            const nordmilkSafe = buyer >= 60;
            const realBrand = credibility >= 60 && supply >= 80;
            const greenwash = ds.greenwashFlag || (credibility > supply + 18);
            const composite = this._composite(ds);

            let performance = window.mySimulation.t(`perf_assertedonly`);
            if (verified && realBrand && nordmilkSafe && composite >= 72) performance = window.mySimulation.t(`perf_verifiedbrand`);
            else if (verified && nordmilkSafe && !greenwash) performance = window.mySimulation.t(`perf_credible`);
            else if (greenwash) performance = window.mySimulation.t(`perf_greenwash`);
            else if (ds.nordmilkLost || buyer < 40) performance = window.mySimulation.t(`perf_lostnordmilk`);
            else if (supply > this.START_SUPPLY + 12) performance = window.mySimulation.t(`perf_improving`);

            const insights = [];
            if (verified && realBrand && nordmilkSafe) insights.push(window.mySimulation.t(`insight_verified`));
            else if (greenwash) insights.push(window.mySimulation.t(`insight_greenwash`));
            else if (ds.nordmilkLost || buyer < 40) insights.push(window.mySimulation.t(`insight_lostnordmilk`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (credibility > supply + 15) insights.push(window.mySimulation.t(`insight_outran`));
            if (supply < 80) insights.push(window.mySimulation.t(`insight_gapopen`));
            if (roi < 0) insights.push(window.mySimulation.t(`insight_negativeroi`));
            if (verified && realBrand && nordmilkSafe && roi >= 4) insights.push(window.mySimulation.t(`insight_payoff`));

            return {
                supply: supply,
                credibility: credibility,
                buyer: buyer,
                roi: roi,
                verified: verified,
                nordmilkSafe: nordmilkSafe,
                realBrand: realBrand,
                greenwash: greenwash,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="sc-cm"><p class="sc-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="sc-cm-chip ` + (ok ? `sc-cm-ok` : `sc-cm-no`) + `">` +
                `<span class="sc-cm-ico">` + (ok ? `✓` : `✕`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="sc-cm-kpi"><div class="sc-cm-kpi-val">` + val +
                `</div><div class="sc-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="sc-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const roiVal = Math.round(Number(s.roi) * 10) / 10;
            const roiStr = (window.mySimulation.language === `es`)
                ? (roiVal.toFixed(1).replace(`.`, `,`) + ` M€`)
                : (`€` + roiVal.toFixed(1) + `M`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="sc-cm">` +
  `<div class="sc-cm-head">` +
    `<div class="sc-cm-score"><div class="sc-cm-score-num">` + Math.round(s.composite) +
       `<span class="sc-cm-score-den">/100</span></div>` +
       `<div class="sc-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="sc-cm-verdict"><div class="sc-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="sc-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="sc-cm-section"><div class="sc-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="sc-cm-chips">` + chip(!!s.verified, t(`cm_t_supply`)) + chip(!!s.nordmilkSafe, t(`cm_t_nordmilk`)) +
      chip(!!s.realBrand, t(`cm_t_brand`)) + chip(!s.greenwash, t(`cm_t_nogreenwash`)) + `</div></div>` +
  `<div class="sc-cm-section"><div class="sc-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="sc-cm-kpis">` +
      kpi(t(`cm_k_supply`), Math.round(s.supply) + `%`, t(`cm_sub_supply`)) +
      kpi(t(`cm_k_credibility`), Math.round(s.credibility), t(`cm_sub_credibility`)) +
      kpi(t(`cm_k_buyer`), Math.round(s.buyer), t(`cm_sub_buyer`)) +
      kpi(t(`cm_k_roi`), roiStr, t(`cm_sub_roi`)) +
    `</div></div>` +
  (insights ? `<div class="sc-cm-section"><div class="sc-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="sc-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.greenwashFlag) return window.mySimulation.t(`hint_greenwash`);
            if (ds.buyer < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_buyer`);
            if (ds.credibility > ds.supply + 15) return window.mySimulation.t(`hint_outran`);
            if (state.currentPeriod >= 3 && ds.supply < 75) return window.mySimulation.t(`hint_gap`);
            if (ds.supply >= this.TARGET_SUPPLY && ds.credibility >= 60 && ds.buyer >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

